INSERT INTO `projects` (`id`, `slug`, `title`, `category`, `description`, `summary`, `image`, `image_alt`, `year`, `live_url`, `github_url`, `featured`, `published`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'bubble-white','Bubble White','E-commerce / Web Application','A Cambodia-focused clothing e-commerce platform covering product discovery, shopping workflows, customer accounts, orders, promotions, image management, and payment integration.','A Cambodia-focused clothing e-commerce platform. The system covers the full commercial path — browsing and product discovery, cart and checkout workflows, customer accounts, order handling, promotions, product image management, and payment integration — together with the administration needed to operate it day to day.','https://i.imgur.com/8HbEl4Q.png','Bubblewhite',NULL,'https://bubblewhite.co',NULL,1,1,1,'2026-09-23 06:14:06','2026-09-23 10:34:10'),(2,'coffee-app','Coffee App','Mobile / Business Application','TODO: one sentence describing what this application does, in business terms.',NULL,'https://i.imgur.com/7TSiTmU.png',NULL,NULL,NULL,NULL,1,1,2,'2026-09-23 06:14:06','2026-09-23 08:27:40'),(3,'check-in-app','Check-in App','Application','TODO: one sentence describing what gets checked in, by whom, and why.',NULL,NULL,NULL,NULL,NULL,NULL,1,1,3,'2026-09-23 06:14:06','2026-09-23 06:36:16'),(4,'buffet-system','Buffet System','Restaurant / POS System','TODO: one sentence on what the system does for a buffet restaurant — ordering, tables, billing, or all three.',NULL,NULL,NULL,NULL,NULL,NULL,1,1,4,'2026-09-23 06:14:06','2026-09-23 06:36:16'),(5,'portfolio','Portfolio','Web Development','This site — a server-rendered Nuxt 4 frontend with a Go API and MySQL behind it, containerised and deployed behind Nginx and Cloudflare.','This site is the smallest honest example of the stack I work in: a server-rendered Nuxt 4 frontend, a Go API handling the one route that genuinely needs a server, MySQL for the data that must persist, and a container setup that runs the same way locally and in production.','https://i.imgur.com/wNJp6eK.png',NULL,NULL,NULL,NULL,1,1,5,'2026-09-23 06:14:06','2026-09-23 08:27:11'),(6,'wordpress-seo','WordPress & SEO','Web / SEO','TODO: one sentence on the kind of WordPress and SEO work you deliver, without naming clients you cannot cite.',NULL,NULL,NULL,NULL,NULL,NULL,1,1,6,'2026-09-23 06:14:06','2026-09-23 06:36:16');
INSERT INTO `project_technologies` (`id`, `project_id`, `name`, `sort_order`) VALUES (58,3,'Flutter',0),(71,6,'WordPress',0),(72,6,'Elementor Pro',1),(73,6,'PHP',2),(74,6,'MySQL',3),(75,6,'Technical SEO',4),(76,6,'Structured Data',5),(77,6,'Cloudflare',6),(78,6,'cPanel',7),(123,5,'Nuxt 4',0),(124,5,'Vue 3',1),(125,5,'TypeScript',2),(126,5,'Tailwind CSS',3),(127,5,'Go',4),(128,5,'MySQL',5),(129,5,'Docker',6),(130,5,'Nginx',7),(131,5,'Cloudflare',8),(132,2,'Flutter',0),(158,1,'Nuxt',0),(159,1,'Vue',1),(160,1,'Tailwind CSS',2),(161,1,'MySQL',3),(162,1,'Cloudflare',4),(163,1,'Payment APIs',5),(164,1,'GO',6),(165,1,'Railway',7);
INSERT INTO `case_studies` (`project_id`, `overview`, `context`, `problem`, `role`, `approach`, `architecture`, `database_notes`, `api_notes`, `security`, `deployment`, `outcome`, `features`, `challenges`, `decisions`, `updated_at`) VALUES (1,'An online clothing store for the Cambodian market, built as a complete commerce system rather than a catalogue site: customers browse and buy, and the business operates orders, stock imagery, and promotions from the same application.','TODO: who the store serves, how they sold before this existed, and what scale it operates at.','TODO: the specific problem the platform was built to solve.','TODO: which parts you owned — data model, API, storefront, admin, deployment.','TODO: how you sequenced the build and why.','TODO: request path, rendering strategy, and where each responsibility lives.','TODO: core tables, key relationships, and the indexes that matter.','TODO: endpoint surface, auth model, and validation strategy.','TODO: authentication, authorization, payment handling, and hardening.','TODO: hosting, TLS, Cloudflare configuration, and release process.','TODO: what the platform does for the business now. No invented metrics.','[\"Product discovery and browsing\", \"Shopping and checkout workflow\", \"Customer accounts\", \"Order management\", \"Promotions\", \"Product image management\", \"Payment integration\"]','[\"TODO: a real constraint you hit, and how you resolved it.\"]','[{\"decision\": \"TODO: a technical decision you made\", \"rationale\": \"TODO: why, and what you traded away\"}]','2026-09-23 10:34:10'),(2,'TODO: what the app is and who uses it.',NULL,NULL,'TODO: which parts you built.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 08:27:40'),(3,'TODO: what the app is and who uses it.',NULL,NULL,'TODO: which parts you built.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 06:36:16'),(4,'TODO: what the system is, who operates it, and in what kind of venue.',NULL,'TODO: what the restaurant was doing before, and what broke at their scale.','TODO: which parts you built.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 06:36:16'),(5,'A portfolio built as a production system rather than a static page, so the engineering choices on display are the ones actually running the site.',NULL,'A portfolio has almost no inherent backend requirement. The interesting constraint is deciding where complexity is justified: adding a database and an API service for their own sake would contradict the judgement the site is meant to demonstrate.','Sole developer — design system, frontend, API, schema, containers, deployment documentation.','Content lives in typed TypeScript modules and is prerendered, so pages ship as static HTML with no runtime data dependency. Only the contact form needs server behaviour, so that is the only thing with an API and a table behind it.','Cloudflare terminates TLS and fronts the origin. Nginx reverse-proxies to the Nuxt server, which prerenders every content route. The browser posts the contact form to a Nuxt server route, which forwards it server-side to the Go API — the API is never reachable from the public internet, so it needs no CORS surface. The Go service validates, rate-limits, and persists to MySQL.','One table, contact_messages, holding the submission plus request metadata for abuse investigation. Migrations are plain, numbered, forward-and-back SQL files — no ORM, because there is no schema complexity to justify one.','Go net/http with a small middleware chain: request ID, structured logging, panic recovery, body-size limit, security headers, and a per-IP token-bucket limiter. Two routes: POST /v1/contact and GET /health.','The API binds to the container network only. Input is validated and length-bounded server-side before it reaches the database, statements are parameterised, error responses never echo internals, and secrets come from the environment rather than the image.','docker compose builds both services against a MySQL container with a persistent volume and health-gated startup ordering. The same compose file plus an env file is what runs in production behind Nginx.','The site is fully prerendered, keyboard accessible, and works with JavaScript-driven animation disabled. Build, typecheck, lint, and the API test suite all run clean.','[\"Prerendered content routes with typed content modules\", \"Dark, light, and system theme with persisted preference\", \"Per-project case-study pages that render only verified sections\", \"Contact API with validation, per-IP rate limiting, and honeypot spam protection\", \"Person, WebSite, and CreativeWork structured data\", \"Generated sitemap and robots.txt\", \"Multi-stage Docker builds for both services with health checks\"]',NULL,'[{\"decision\": \"Prerender content routes instead of serving them from the database\", \"rationale\": \"The content changes when I change it, not per request. Prerendering removes the database from the critical path for every page a visitor actually reads, so the site stays up and fast even if the API is down.\"}, {\"decision\": \"Proxy the contact form through the Nuxt server rather than calling Go from the browser\", \"rationale\": \"It keeps the Go service unreachable from the internet and removes the need for a public CORS policy. The cost is one extra internal hop on a route that runs a few times a day.\"}, {\"decision\": \"No CMS or admin panel\", \"rationale\": \"One author editing typed files gets type safety and version history for free. An admin panel would add authentication, sessions, and an attack surface to solve a problem that does not exist yet.\"}]','2026-09-23 08:27:11'),(6,'TODO: the scope of this work — build, migration, optimisation, or ongoing maintenance.',NULL,NULL,'TODO: what you were responsible for.','TODO: your technical SEO process — audit, fixes, measurement.',NULL,NULL,NULL,NULL,'TODO: hosting, caching, and CDN configuration you set up.',NULL,NULL,NULL,NULL,'2026-09-23 06:36:16');
INSERT INTO `experience_entries` (`id`, `label`, `title`, `company`, `period`, `location`, `is_current`, `technologies`, `description`, `sort_order`) VALUES (1,'Nov 2022 - Dec 2025','IT Manager & Full-Stack Developer','2M Media','Nov 2022 - Dec 2025','Khan 7 Makara , Phnom Penh',0,'[]','* Lead end-to-end development and technical operations across **web, mobile, e-commerce, CRM, POS, payment, media, and business management platforms**.\n* Architect and develop scalable full-stack systems using **Go, Laravel/PHP, Nuxt 3, Vue.js, MySQL, REST APIs, and Flutter**, from system design through production deployment.\n* Design and integrate **payment and financial workflows**, including KHQR, Bakong, PPCBank, ABA PayWay, real-time payment verification, and transaction processing.\n* Manage **cloud infrastructure, Linux servers, DigitalOcean, Railway, Cloudflare R2, Docker, DNS, SSL, GitHub Actions, and CI/CD**, ensuring reliable production deployments.\n* Lead backend architecture, database design, authentication, **JWT security, RBAC/permissions, device/session management, API security, performance optimization, and system monitoring**.\n* Build high-performance **media and livestream platforms**, including video storage, streaming infrastructure, social sharing, SEO/Open Graph optimization, and scalable API services.\n* Provide technical leadership across the full software lifecycle—**architecture, development, troubleshooting, deployment, security, optimization, and ongoing IT operations**—while evaluating new technologies and improving business processes.',0),(7,'Sep 2021 -Dec 2021','Web Development (Internship)','Technology Solution Development TSD Co,.Ltd.','Sep 2021 -Dec 2021','#D49, StreetVI-18, Toul Sangke Commune, Reussey Keo District, Phnom Penh, Cambodia',0,'[\"CodeIgniter\", \"Php\", \"Css\", \"Html\", \"bootstrap\", \"Mysql\"]','* Developed and maintained web applications using **PHP and CodeIgniter 3**.\n* Built and customized web application features based on business requirements.\n* Customized and maintained **inventory management (Custom INV) systems**, including product and stock-related functionality.\n* Provided technical support and troubleshooting for customers using the web application.\n* Fixed bugs, investigated system issues, and improved existing application functionality.\n* Worked with databases and backend functionality to support daily business operations.\n* Collaborated with team members to test, deploy, and maintain web application features.',7),(9,'Dec 2021 -Nov 2022','Full-Stack Developer','Technology Solution Development TSD Co,.Ltd.','Dec 2021 -Nov 2022','#D49, StreetVI-18, Toul Sangke Commune, Reussey Keo District, Phnom Penh, Cambodia',0,'[\"php\", \"laravel\", \"mysql\", \"codeIgniter\", \"html\", \"css\", \"boostrap\"]','* Developed and maintained multiple **client web applications** using **PHP, Laravel, and CodeIgniter**.\n* Developed and integrated **Telegram Chat Bots** to automate customer communication and business processes.\n* Built and customized web application features based on client requirements.\n* Worked with databases, backend logic, APIs, and third-party service integrations.\n* Collaborated with UI/UX and design teams to implement **pixel-perfect, responsive user interfaces**.\n* Provided technical support, troubleshooting, and maintenance for client projects.\n* Fixed bugs, optimized existing features, and improved application performance and reliability.\n* Participated in testing, deployment, and ongoing maintenance of production applications.',6),(10,'Dec 2025 - Present','Founder & Full-Stack Technology Lead','Go Tect Company Solution','Dec 2025 - Present',NULL,1,'[]','Founder and technology lead responsible for delivering end-to-end software and IT solutions for businesses, from business requirements and system architecture through development, deployment, security, and ongoing technical operations.\n\n\n\nLead the design and development of custom web, mobile, POS, CRM, e-commerce, restaurant, booking, payment, and business management platforms.\n\nArchitect scalable systems using Go, Laravel/PHP, Nuxt 3, Vue.js, Flutter, MySQL, REST APIs, JWT, and cloud infrastructure.\n\nDevelop and integrate payment solutions including KHQR, Bakong, PPCBank, ABA PayWay, and third-party payment and business APIs.\n\nManage production infrastructure and DevOps across DigitalOcean, Railway, Cloudflare, Cloudflare R2, Linux, Docker, GitHub Actions, DNS, SSL, CI/CD, monitoring, and deployment environments.\n\nBuild modern media, video, livestream, and content platforms, including cloud storage, video delivery, API services, social sharing, SEO, and Open Graph optimization.\n\nLead technical strategy, software architecture, security, performance optimization, database design, troubleshooting, and technology decisions across projects.\n\nWork directly with business requirements and translate operational needs into reliable, scalable, and maintainable technology solutions.',-1);
INSERT INTO `capabilities` (`id`, `slug`, `title`, `description`, `icon`, `items`, `sort_order`) VALUES (1,'architecture','Software Architecture','System architecture, modular design, maintainable project structures, and scalable application design.','lucide:layout-template','[\"System design\", \"Modular structure\", \"Domain separation\", \"Code review\", \"Documentation\"]',0),(2,'backend','Backend & APIs','Business logic, REST APIs, authentication, authorization, validation, and third-party integrations.','lucide:server','[\"Go\", \"Laravel / PHP\", \"REST\", \"Auth & sessions\", \"Validation\", \"Integrations\"]',1),(3,'frontend','Frontend','Responsive, API-driven interfaces with a typed component architecture and measured performance.','lucide:monitor','[\"Vue 3\", \"Nuxt\", \"TypeScript\", \"Tailwind CSS\", \"SSR / SSG\", \"Accessibility\"]',2),(4,'mobile','Mobile','Cross-platform mobile applications sharing the same backend contracts as the web clients.','lucide:smartphone','[\"Flutter\", \"Android\", \"iOS\", \"Firebase\", \"Mobile API integration\", \"Release builds\"]',3),(5,'data','Data','Relational design that holds up under real data volume, with integrity and recovery planned in.','lucide:database','[\"MySQL\", \"Schema design\", \"Migrations\", \"Indexing\", \"Query optimisation\", \"Backup & recovery\"]',4),(6,'infrastructure','Infrastructure','Provisioning, serving, and routing production applications on Linux and managed platforms.','lucide:cloud','[\"Linux / Ubuntu\", \"Docker\", \"Nginx\", \"VPS\", \"Railway\", \"DigitalOcean\", \"Cloudflare\", \"cPanel\"]',5),(7,'security','Security','Application and infrastructure hardening treated as part of the build, not a later pass.','lucide:shield-check','[\"Authentication\", \"Authorization\", \"Input validation\", \"HTTPS / TLS\", \"API protection\", \"Rate limiting\", \"Secure configuration\"]',6),(8,'production','Production','Keeping systems observable and recoverable once real users depend on them.','lucide:activity','[\"Logging\", \"Monitoring\", \"Health checks\", \"Error handling\", \"Backups\", \"Deployment\", \"Maintenance\"]',7);
INSERT INTO `services` (`id`, `slug`, `title`, `description`, `icon`, `sort_order`) VALUES (1,'web-apps','Custom Web Applications','Business systems, dashboards, portals, customer applications, and internal tools built around your actual workflow.','lucide:app-window',1),(2,'backend','Backend & API Systems','Secure APIs, business logic, integrations, authentication, and the database design underneath them.','lucide:server-cog',0),(3,'mobile','Mobile Applications','Cross-platform mobile applications using Flutter, sharing one backend with your web product.','lucide:smartphone',2),(4,'ecommerce','E-commerce','Product catalogues, customer accounts, orders, payments, promotions, and the administration system that runs them.','lucide:shopping-bag',3),(5,'wordpress-seo','WordPress & SEO','Professional websites with Elementor, plus technical SEO, performance optimisation, and hosting setup.','lucide:search',4),(6,'deployment','Production Deployment','Docker, Linux, VPS, Nginx, Cloudflare, backups, monitoring, and the operational work after launch.','lucide:rocket',5);
INSERT INTO `principles` (`id`, `slug`, `title`, `description`, `icon`, `sort_order`) VALUES (1,'architecture','Architecture','Designed before implementation, so the structure survives the second and third feature.','lucide:compass',0),(2,'security','Security','Considered from the application layer down to the infrastructure it runs on.','lucide:lock',1),(3,'reliability','Reliability','Errors, backups, monitoring, and recovery are part of the system, not an afterthought.','lucide:heart-pulse',2),(4,'maintainability','Maintainability','Clean structure and documentation so future development does not start with archaeology.','lucide:wrench',3);
INSERT INTO `pillars` (`id`, `slug`, `title`, `description`, `sort_order`) VALUES (1,'experience','Experience','Professional full-time software development since 2020.',0),(2,'technical-breadth','Technical breadth','Backend, frontend, mobile, databases, APIs, infrastructure, WordPress, SEO, and cloud deployment.',1),(3,'production-ownership','Production ownership','Architecture, development, database, security, deployment, monitoring, backup, and maintenance — not just writing code.',2);
INSERT INTO `content_translations` (`id`, `entity`, `entity_id`, `field`, `locale`, `value`, `updated_at`) VALUES (10,'setting',0,'headline','km','ជំរាបសួរ, ខ្ញុំបាទ','2026-09-25 05:05:26'),(12,'setting',0,'headline_tail','km','គង់ ចន្ទសិលា','2026-09-25 05:05:26'),(15,'experience',1,'period','km','Nov 2022 - Dec 2025','2026-09-24 04:02:35'),(59,'experience',7,'title','km','Web Development (Internship)','2026-09-24 04:02:07'),(60,'experience',7,'company','km','Technology Solution Development TSD Co,.Ltd.','2026-09-24 04:02:07'),(61,'experience',7,'location','km','#D49, ផ្លូវលេខ ១៨, សង្កាត់ទួលសង្កែ, ខណ្ឌឫស្សីកែវ, រាជធានីភ្នំពេញ, ព្រះរាជាណាចក្រកម្ពុជា។','2026-09-24 04:02:07'),(62,'experience',7,'period','km','កញ្ញា 2021 - ធ្នូ 2021','2026-09-24 04:02:07'),(63,'experience',7,'description','km','* បានអភិវឌ្ឍ និងថែទាំកម្មវិធីបណ្តាញវ៉ិបសាយដោយប្រើប្រាស់ PHP និង CodeIgniter 3។\n* បានបង្កើត និងកែសម្រួលមុខងារកម្មវិធីវ៉ិបសាយផ្អែកលើតម្រូវការអាជីវកម្ម។\n* បានកែសម្រួល និងថែទាំប្រព័ន្ធគ្រប់គ្រងសារពើភណ្ឌ (Custom INV) រួមទាំងមុខងារទាក់ទងនឹងផលិតផល និងស្តុក។\n* បានផ្តល់ការគាំទ្រផ្នែកបច្ចេកទេស និងការដោះស្រាយបញ្ហាសម្រាប់អតិថិជនដែលប្រើប្រាស់កម្មវិធីវ៉ិបសាយ។\n* បានជួសជុលកំហុសឆ្គង (Bugs) ស្រាវជ្រាវបញ្ហាប្រព័ន្ធ និងកែលម្អមុខងារកម្មវិធីที่มีស្រាប់។\n* បានធ្វើការជាមួយមូលដ្ឋានទិន្នន័យ (Databases) និងមុខងារផ្នែកខាងក្រោយ (Backend) ដើម្បីគាំទ្រប្រតិបត្តិការអាជីវកម្មប្រចាំថ្ងៃ។\n* បានជួយអ្នកប្រើប្រាស់ និងអតិថិជនលើការប្រើប្រាស់ប្រព័ន្ធ បញ្ហាបច្ចេកទេស។\n* បានសហការជាមួយសមាជិកក្រុមដើម្បីធ្វើតេស្ត ដាក់ឱ្យដំណើរការ និងថែទាំមុខងារកម្មវិធីវ៉ិបសាយ។','2026-09-24 04:02:07'),(64,'experience',7,'label','km','កញ្ញា 2021 - ធ្នូ 2021','2026-09-24 04:02:07'),(100,'experience',9,'company','km','Technology Solution Development TSD Co,.Ltd.','2026-09-24 04:01:50'),(101,'experience',9,'title','km','Full-Stack Developer','2026-09-24 04:01:50'),(102,'experience',9,'description','km','* បានអភិវឌ្ឍ និងថែទាំកម្មវិធីបណ្តាញវ៉ិបសាយរបស់អតិថិជនជាច្រើន ដោយប្រើប្រាស់ **PHP, Laravel និង CodeIgniter**។\n* បានអភិវឌ្ឍ និងដាក់បញ្ចូល **Telegram Chat Bots** ដើម្បីស្វ័យប្រវត្តិកម្មការទំនាក់ទំនងជាមួយអតិថិជន និងដំណើរការអាជីវកម្ម។\n* បានបង្កើត និងកែសម្រួលមុខងារកម្មវិធីវ៉ិបសាយផ្អែកលើតម្រូវការរបស់អតិថិជន។\n* បានធ្វើការជាមួយមូលដ្ឋានទិន្នន័យ (Databases) ឡូជីខលផ្នែកខាងក្រោយ (Backend logic) APIs និងការសមាហរណកម្មសេវាកម្មភាគីទីបី (Third-party service integrations)។\n* បានសហការជាមួយក្រុម UI/UX និងក្រុមឌីសាញ ដើម្បីអនុវត្ត **ចំណុចប្រទាក់អ្នកប្រើប្រាស់ (User Interfaces) ដែលមានភាពស្របគ្នា និងឆ្លើយតបបានល្អ (Responsive)**។\n* បានផ្តល់ការគាំទ្រផ្នែកបច្ចេកទេស ការដោះស្រាយបញ្ហា និងការថែទាំសម្រាប់គម្រោងរបស់អតិថិជន។\n* បានជួសជុលកំហុសឆ្គង (Bugs) ធ្វើឱ្យមុខងារដែលមានស្រាប់ប្រសើរឡើង ក៏ដូចជាបង្កើនល្បឿន និងភាពជឿជាក់របស់កម្មវិធី។\n* បានចូលរួមក្នុងការធ្វើតេស្ត ដាក់ឱ្យដំណើរការ (Deployment) និងការថែទាំជាប្រចាំនូវកម្មវិធីនៅលើប្រព័ន្ធផលិតកម្ម (Production applications)។','2026-09-24 04:01:50'),(103,'experience',9,'period','km','ធ្នូ 2021 - វិច្ឆិកា 2022','2026-09-24 04:01:50'),(104,'experience',9,'location','km','#D49, ផ្លូវលេខ ១៨, សង្កាត់ទួលសង្កែ, ខណ្ឌឫស្សីកែវ, រាជធានីភ្នំពេញ, ព្រះរាជាណាចក្រកម្ពុជា។','2026-09-24 04:01:50'),(105,'experience',9,'label','km','ធ្នូ 2021 - វិច្ឆិកា 2022','2026-09-24 04:01:50'),(185,'experience',1,'title','km','IT Manager & Full-Stack Developer','2026-09-24 04:02:35'),(186,'experience',1,'company','km','2M Media','2026-09-24 04:02:35'),(187,'experience',1,'location','km','ខណ្ឌ៧មករា,រាជធានីភ្នំពេញ','2026-09-24 04:02:35'),(188,'experience',1,'label','km','វិច្ឆិកា 2022 - ធ្នូ 2025','2026-09-24 04:02:35'),(189,'experience',1,'description','km','* ដឹកនាំការអភិវឌ្ឍពីต้นจนจบ (End-to-end) និងប្រតិបត្តិការបច្ចេកទេសលើប្រព័ន្ធបណ្តាញវ៉ិបសាយ កម្មវិធីទូរស័ព្ទ អុីកូមឺស (E-commerce) CRM, POS, ប្រព័ន្ធទូទាត់ ប្រព័ន្ធផ្សព្វផ្សាយ និងវេទិកាគ្រប់គ្រងអាជីវកម្ម។\n* រចនា និងអភិវឌ្ឍប្រព័ន្ធ Full-stack ដែលមាន khả năngពង្រីក (Scalable) ដោយប្រើប្រាស់ **Go, Laravel/PHP, Nuxt 3, Vue.js, MySQL, REST APIs និង Flutter** ចាប់ពីការរចនាប្រព័ន្ធរហូតដល់ការដាក់ឱ្យដំណើរការលើ Production។\n* រចនា និងដាក់បញ្ចូលដំណើរការទូទាត់ និងហិរញ្ញវត្ថុ រួមមាន **KHQR, Bakong, PPCBank, ABA PayWay**, ការផ្ទៀងផ្ទាត់ការទូទាត់ពេលវេលាជាក់ស្តែង (Real-time payment verification) និងការដំណើរការប្រតិបត្តិការ (Transaction processing)។\n* គ្រប់គ្រងហេដ្ឋារចនាសម្ព័ន្ធពពក (Cloud infrastructure), សឺវើ Linux, **DigitalOcean, Railway, Cloudflare R2, Docker, DNS, SSL, GitHub Actions និង CI/CD** ដោយធានាបាននូវការដាក់ឱ្យដំណើរការលើ Production ប្រកបដោយភាពជឿជាក់។\n* ដឹកនាំស្ថាបត្យកម្មផ្នែកខាងក្រោយ (Backend architecture) การរចនាមូលដ្ឋានទិន្នន័យ ការផ្ទៀងផ្ទាត់ភាពត្រឹមត្រូវ សុវត្ថិភាព JWT, **RBAC/permissions**, ការគ្រប់គ្រងឧបករណ៍/សម័យសវនាការ (Session management) សុវត្ថិភាព API ការបង្កើនប្រសិទ្ធភាព និងការត្រួតពិនិត្យប្រព័ន្ធ។\n* បង្កើតវេទិកាប្រព័ន្ធផ្សព្វផ្សាយ និងការផ្សាយបន្តផ្ទាល់ (Livestream) ដែលមានប្រសិទ្ធភាពខ្ពស់ រួមទាំងការផ្ទុកវីដេអូ ហេដ្ឋារចនាសម្ព័ន្ធស្ទ្រីម ការចែករំលែកតាមបណ្តាញសង្គម ការបង្កើនប្រសិទ្ធភាព **SEO/Open Graph** និងសេវាកម្ម API ที่មាន khả năngពង្រីក។\n* ផ្តល់នូវភាពជាผู้นាំផ្នែកបច្ចេកទេសពេញមួយវដ្តជីវិតផ្នែកទន់ (Software lifecycle) — ស្ថាបត្យកម្ម ការអភិវឌ្ឍ การแก้ปัญหา การដាក់ឱ្យដំណើរការ សុវត្ថិភាព ការបង្កើនប្រសិទ្ធភាព និងប្រតិបត្តិការ IT បន្តបន្ទាប់ — ព្រមទាំងវាយតម្លៃបច្ចេកវិទ្យាថ្មីៗ និងកែលម្អដំណើរការអាជីវកម្មផងដែរ។','2026-09-24 04:02:35'),(190,'experience',10,'period','km','ធ្នូ 2025 - បច្ចុប្បន្ន','2026-09-24 04:02:42'),(191,'experience',10,'label','km','ធ្នូ 2025 - បច្ចុប្បន្ន','2026-09-24 04:02:42'),(192,'experience',10,'description','km','* ជាអ្នកទទួលខុសត្រូវក្នុងការផ្តល់នូវដំណោះស្រាយផ្នែកទន់ និង IT បរិបូរណ៍ពីต้นจนจบ (End-to-end) សម្រាប់អាជីវកម្ម ចាប់ពីតម្រូវការអាជីវកម្ម និងស្ថាបត្យកម្មប្រព័ន្ធ រហូតដល់ការអភិវឌ្ឍ ការដាក់ឱ្យដំណើរការ សុវត្ថិភាព និងប្រតិបត្តិការបច្ចេកទេសបន្តបន្ទាប់។\n* ដឹកនាំការរចនា និងអភិវឌ្ឍប្រព័ន្ធបណ្តាញវ៉ិបសាយ កម្មវិធីទូរស័ព្ទ POS, CRM, អ៊ីកូមឺស (E-commerce), ភោជនីយដ្ឋាន, ប្រព័ន្ធកក់ប្រាក់ (Booking), ប្រព័ន្ធទូទាត់ និងវេទិកាគ្រប់គ្រងអាជីវកម្មតាមតម្រូវការ။\n* រចនាស្ថាបត្យកម្មប្រព័ន្ធដែលមានលក្ខណៈអាចពង្រីកបាន (Scalable systems) ដោយប្រើប្រាស់ **Go, Laravel/PHP, Nuxt 3, Vue.js, Flutter, MySQL, REST APIs, JWT** និងហេដ្ឋារចនាសម្ព័ន្ធពពក (Cloud infrastructure)។\n* អភិវឌ្ឍ និងសមាហរណកម្មដំណោះស្រាយទូទាត់ប្រាក់ រួមមាន **KHQR, Bakong, PPCBank, ABA PayWay** និង APIs ភាគីទីបីសម្រាប់អាជីវកម្ម។\n* គ្រប់គ្រងហេដ្ឋារចនាសម្ព័ន្ធ Production និង DevOps លើ **DigitalOcean, Railway, Cloudflare, Cloudflare R2, Linux, Docker, GitHub Actions, DNS, SSL, CI/CD**, ការត្រួតពិនិត្យប្រព័ន្ធ และបរិយាកាសដាក់ឱ្យដំណើរការ។\n* បង្កើតប្រព័ន្ធផ្សព្វផ្សាយ វីដេអូ ការផ្សាយបន្តផ្ទាល់ (Livestream) និងវេទិកាខ្លឹមសារទំនើបៗ រួមទាំងការផ្ទុកទិន្នន័យលើពពក ការបញ្ជូនវីដេអូ សេវាកម្ម API ការចែករំលែកតាមបណ្តាញសង្គម **SEO និងការបង្កើនប្រសិទ្ធភាព Open Graph**។\n* ដឹកនាំយុទ្ធសាស្ត្របច្ចេកទេស ស្ថាបត្យកម្មប្រព័ន្ធទន់ (Software architecture) សុវត្ថិភាព ការបង្កើនប្រសិទ្ធភាព ការរចនាមូលដ្ឋានទិន្នន័យ ការដោះស្រាយបញ្ហា និងការសម្រេចចិត្តលើបច្ចេកវិទ្យា across projects។\n* ធ្វើការផ្ទាល់ជាមួយតម្រូវការអាជីវកម្ម និងបកប្រែតម្រូវការប្រតិបត្តិការឱ្យទៅជាដំណោះស្រាយបច្ចេកវិទ្យាដែលគួរឱ្យទុកចិត្ត អាចពង្រីកបាន និងងាយស្រួលថែទាំ។','2026-09-24 04:02:42'),(193,'experience',10,'company','km','Go Tect Company Solution','2026-09-24 04:02:42'),(194,'experience',10,'title','km','Founder & Full-Stack Technology Lead','2026-09-24 04:02:42'),(256,'setting',0,'positioning','km','វិស្វករសូហ្វវែរ Full-Stack និងជាប្រធានដឹកនាំផ្នែកបច្ចេកវិទ្យា ដែលមានបទពិសោធន៍ចាប់តាំងពីឆ្នាំ ២០២០ មក ដោយផ្ដោតលើស្ថាបត្យកម្ម End-to-End, កម្មវិធី Web/Mobile ប្រសិទ្ធភាពខ្ពស់, ហេដ្ឋារចនាសម្ព័ន្ធ Cloud និងការតភ្ជាប់ប្រព័ន្ធទូទាត់ប្រាក់ដែលមានសុវត្ថិភាព។','2026-09-25 05:05:26'),(257,'setting',0,'availability','km','មានភាពរួចរាល់សម្រាប់តួនាទីជាអ្នកដឹកនាំ, ការផ្តល់ប្រឹក្សាយោបល់បច្ចេកទេស (Consulting) និងគម្រោងស្ថាបត្យកម្ម Full-Stack។ បើកចំហចំពោះការងារក្នុងស្រុក និងការសហការពីចម្ងាយ (Remote)។','2026-09-25 05:05:26'),(258,'setting',0,'description','km','ស្វែងយល់ពីប្រវត្តិរូប និងស្នាដៃរបស់ គង់ ចាន់សីលា អ្នកអភិវឌ្ឍន៍ប្រព័ន្ធសូហ្វវែរ Full-Stack និង Tech Lead។ ឯកទេសខាង Go, Laravel, Nuxt 3, Vue.js, Flutter, Cloud Infrastructure និងប្រព័ន្ធដែលអាចពង្រីកតាមតម្រូវការអាជីវកម្ម។','2026-09-25 05:05:26'),(261,'setting',0,'tagline','km','បង្កើតប្រព័ន្ធសូហ្វវែរពេញលេញ មានស្ថិរភាព និងអាចពង្រីកបាន ចាប់ពីមូលដ្ឋានទិន្នន័យរហូតដល់ Production។','2026-09-25 05:05:26'),(263,'setting',0,'about_paragraphs','km','[\"ខ្ញុំជាអ្នកអភិវឌ្ឍន៍ប្រព័ន្ធសូហ្វវែរ Full-Stack ដែលមានបទពិសោធន៍ធ្វើការងារវិជ្ជាជីវៈចាប់តាំងពីឆ្នាំ ២០២០ មក ដោយផ្ដោតលើស្ថាបត្យកម្មប្រព័ន្ធពេញលេញ (End-to-End), កម្មវិធី Web និង Mobile ប្រសិទ្ធភាពខ្ពស់ ព្រមទាំងហេដ្ឋារចនាសម្ព័ន្ធ Cloud។ ការងារភាគច្រើនរបស់ខ្ញុំគឺការបង្កើត និងគ្រប់គ្រងប្រព័ន្ធទាំងមូល ជាជាងការធ្វើតែមុខងារដាច់ដោយឡែក — ចាប់តាំងពីការរចនាម៉ូដែលទិន្នន័យ, ការបង្កើត API ដែលមានសុវត្ថិភាព, ការរចនាចំណុចប្រទាក់អ្នកប្រើប្រាស់ រហូតដល់ការដាក់ឱ្យដំណើរការលើ Cloud និងការថែទាំប្រព័ន្ធ Production។ ខ្ញុំតែងតែផ្តល់អាទិភាពលើរចនាសម្ព័ន្ធកូដដែលមានរបៀបរៀបរយ ងាយស្រួលថែទាំ និងរៀបចំផែនការការពារបញ្ហាទុកជាមុន មុនពេលប្រព័ន្ធត្រូវដាក់ឱ្យប្រើប្រាស់ផ្លូវការ។\"]','2026-09-25 05:05:26'),(270,'setting',0,'role','km','Full-Stack Software Developer','2026-09-25 05:05:26'),(277,'pillar',1,'title','km','បទពិសោធន៍ការងារ','2026-09-24 04:07:41'),(278,'pillar',1,'description','km','មានបទពិសោធន៍ធ្វើការងារអភិវឌ្ឍន៍សូហ្វវែរអាជីពពេញម៉ោងចាប់តាំងពីឆ្នាំ ២០២០ មក។','2026-09-24 04:07:41'),(279,'pillar',2,'title','km','វិសាលភាពជំនាញបច្ចេកទេស','2026-09-24 04:07:56'),(280,'pillar',2,'description','km','មានជំនាញគ្របដណ្តប់ពេញលេញលើ Backend, Frontend, Mobile, Databases, APIs, ហេដ្ឋារចនាសម្ព័ន្ធ (Infrastructure), WordPress, SEO និងការដាក់ឱ្យដំណើរការលើ Cloud។','2026-09-24 04:07:56'),(281,'pillar',3,'title','km','ការទទួលខុសត្រូវលើប្រព័ន្ធ Production','2026-09-24 04:08:10'),(282,'pillar',3,'description','km','ទទួលខុសត្រូវទាំងស្រុងលើស្ថាបត្យកម្មប្រព័ន្ធ, ការអភិវឌ្ឍ, ការរចនាមូលដ្ឋានទិន្នន័យ, សុវត្ថិភាព, ការដាក់ឱ្យដំណើរការ (Deployment), ការត្រួតពិនិត្យប្រព័ន្ធ, ការបម្រុងទុកទិន្នន័យ (Backups) និងការថែទាំ — មិនមែនត្រឹមតែការសរសេរកូដនោះទេ។','2026-09-24 04:08:10'),(283,'principle',1,'title','km','ស្ថាបត្យកម្មប្រព័ន្ធ','2026-09-24 04:10:18'),(284,'principle',1,'description','km','ត្រូវបានរៀបចំ និងរចនាយ៉ាងល្អិតល្អន់មុនពេលចាប់ផ្តើមសរសេរកូដ ដើម្បីធានាថារចនាសម្ព័ន្ធប្រព័ន្ធនៅតែមានរបៀបរៀបរយ ងាយស្រួលថែទាំ និងអាចពង្រីកបានយ៉ាងរលូន នៅពេលបន្ថែមមុខងារថ្មីៗជាបន្តបន្ទាប់។','2026-09-24 04:10:18'),(285,'principle',2,'title','km','សុវត្ថិភាពប្រព័ន្ធ','2026-09-24 04:11:00'),(286,'principle',2,'description','km','ត្រូវបានគិតគូរ និងរៀបចំឡើងយ៉ាងគ្រប់ជ្រុងជ្រោយ — ចាប់តាំងពីកម្រិតកម្មវិធី (Application Layer) រហូតដល់ហេដ្ឋារចនាសម្ព័ន្ធផ្នែកខាងក្រោមដែលប្រព័ន្ធកំពុងដំណើរការ។','2026-09-24 04:11:00'),(289,'principle',3,'title','km','ភាពជឿជាក់ និងស្ថិរភាពប្រព័ន្ធ','2026-09-24 04:11:28'),(290,'principle',3,'description','km','ការដោះស្រាយកំហុសឆ្គង (Error Handling), ការបម្រុងទុកទិន្នន័យស្វ័យប្រវត្តិ (Automated Backups), ការត្រួតពិនិត្យប្រព័ន្ធជាប្រចាំ (Monitoring) និងផែនការសង្គ្រោះប្រព័ន្ធ (Disaster Recovery) ត្រូវបានបញ្ចូលទៅក្នុងរចនាសម្ព័ន្ធប្រព័ន្ធតាំងពីដំបូង ដោយមិនមែនជាកិច្ចការដែលត្រូវធ្វើតាមក្រោយនោះទេ។','2026-09-24 04:11:28'),(291,'principle',4,'description','km','រចនាសម្ព័ន្ធកូដដែលមានរបៀបរៀបរយ និងឯកសារបច្ចេកទេសច្បាស់លាស់ ត្រូវបានរៀបចំឡើងเพื่อឱ្យការអភិវឌ្ឍបន្ថែមនៅពេលអនាគតប្រព្រឹត្តទៅដោយរលូន និងមានប្រសិទ្ធភាព ដោយមិនបាច់ចំណាយពេលស្វែងយល់ពីភាពស្មុគស្មាញនៃកូដចាស់ៗឡើយ។','2026-09-24 04:12:00'),(292,'principle',4,'title','km','ភាពងាយស្រួលក្នុងការថែទាំ','2026-09-24 04:12:00'),(306,'setting',0,'name','km','គង់ ចន្ទសិលា','2026-09-25 05:05:26');
INSERT INTO `site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('about_paragraphs','[\"I am a full-stack software developer with professional experience since 2020, specializing in end-to-end system architecture, high-performance web and mobile applications, and cloud infrastructure. Most of my work involves building and running complete systems rather than isolated features—designing data models, building secure APIs, crafting responsive user interfaces, and managing cloud deployment and production operations. I prioritize clean, maintainable architecture that remains readable over time and plan for potential failure modes before code ever reaches production.\"]','2026-09-25 05:05:26'),('availability','Available for leadership roles, high-impact consulting, and full-stack architecture projects. Open to local and remote collaborations.','2026-09-25 05:05:26'),('contact_enabled','true','2026-09-25 05:05:26'),('description','Explore the portfolio of Kong Chansila, a Full-Stack Software Developer and Tech Lead with experience since 2020. Specializing in Go, Laravel, Nuxt, Vue, Flutter, cloud infrastructure, and end-to-end scalable systems.','2026-09-25 05:05:26'),('headline','Hi, I\'m','2026-09-25 05:05:26'),('headline_tail','KONG CHANSILA','2026-09-25 05:05:26'),('hero_stack','[\"Go\",\"Laravel\",\"Vue\",\"Nuxt\",\"Flutter\",\"MySQL\",\"Docker\",\"Cloudflare\"]','2026-09-25 05:05:26'),('location','Cambodia','2026-09-25 05:05:26'),('name','KONG CHANSILA','2026-09-25 05:05:26'),('portrait','https://i.imgur.com/Yg06B6c.png','2026-09-25 05:05:26'),('portrait_alt','Kong Chansila, Full-Stack Software Developer','2026-09-25 05:05:26'),('positioning','Full-Stack Software Engineer & Technology Lead specializing in end-to-end architecture, high-performance web/mobile applications, cloud infrastructure, and secure payment integrations.','2026-09-25 05:05:26'),('profiles','[{\"label\":\"Github\",\"href\":\"/\",\"icon\":\"lucide:link\",\"image\":\"https://i.imgur.com/MAT8gZQ.png\"},{\"label\":\"Facebook\",\"href\":\"/\",\"image\":\"https://i.imgur.com/vIFUXd7.png\"},{\"label\":\"Instagram\",\"href\":\"/\",\"image\":\"https://i.imgur.com/qQTaPHD.png\"},{\"label\":\"Telegram\",\"href\":\"/\",\"image\":\"https://i.imgur.com/0GZCKuv.png\"}]','2026-09-25 05:05:26'),('resume_file','','2026-09-25 05:05:26'),('role','Full-Stack Software Developer','2026-09-25 05:05:26'),('start_year','2020','2026-09-25 05:05:26'),('tagline','Building complete, resilient, and scalable systems from database to production.','2026-09-25 05:05:26'),('wordpress_seo_stack','[\"WordPress\",\"Elementor\",\"Elementor Pro\",\"PHP\",\"MySQL\",\"Technical SEO\",\"On-page SEO\",\"Performance\",\"Mobile SEO\",\"Sitemap\",\"Structured Data\",\"Cloudflare\",\"cPanel\"]','2026-09-25 05:05:26');

